solution:
// Return the area covered by the union of axis-aligned rectangles.
// Each rectangle is (x1, y1, x2, y2), where (x1, y1) and (x2, y2) are two
// opposite corners given in any order. Area covered by several rectangles
// counts once. A rectangle with zero width or zero height covers nothing, and
// an empty list gives 0.
//
// Return -1 if any coordinate has absolute value greater than 1_000_000.
//
// Examples:
//   rect_union_area([(0, 0, 4, 4), (2, 2, 6, 6)]) == 28
//   rect_union_area([(3, 3, 1, 1)]) == 4
fn rect_union_area(rects: List[(Int, Int, Int, Int)]) -> Int {
  let limit = 1_000_000;
  let mut norm: List[(Int, Int, Int, Int)] = [];
  for (x1, y1, x2, y2) in rects {
    if abs(x1) > limit || abs(y1) > limit || abs(x2) > limit || abs(y2) > limit {
      return -1;
    }
    // Corners may come in any order; store (left, bottom, right, top).
    norm = push(norm, (min(x1, x2), min(y1, y2), max(x1, x2), max(y1, y2)));
  }
  let xs = sort(unique(flat_map(norm, |r| [r.0, r.2])));
  let ys = sort(unique(flat_map(norm, |r| [r.1, r.3])));
  let mut total = 0;
  // Coordinate compression: each grid cell is either fully covered or not.
  for i in range(0, len(xs) - 1) {
    for j in range(0, len(ys) - 1) {
      if covered(norm, xs[i], ys[j], xs[i + 1], ys[j + 1]) {
        total = total + (xs[i + 1] - xs[i]) * (ys[j + 1] - ys[j]);
      }
    }
  }
  total
}

// True if one rectangle contains the cell [x0, x1] x [y0, y1].
fn covered(rects: List[(Int, Int, Int, Int)], x0: Int, y0: Int, x1: Int, y1: Int) -> Bool {
  for (a, b, c, d) in rects {
    if a <= x0 && x1 <= c && b <= y0 && y1 <= d {
      return true;
    }
  }
  false
}
